CREATE OR REPLACE VIEW public.public_campaign_reports AS SELECT id, title, description, slug, published, published_at, header_image_url, profile_image_url, categories, hide_categories, template, created_at, updated_at, custom_links FROM campaign_reports r WHERE published = true AND access_code IS NULL; GRANT SELECT ON public.public_campaign_reports TO anon, authenticated; GRANT ALL ON public.public_campaign_reports TO service_role;